-- Productos de la organización 3 (Futura Farma - Mavisa), del archivo «ACT_PRODUCTOS.xls»
-- (391 productos: 156 de la 3-01 y 235 de la 3-02; la fila de la localidad 0 solo repite los nombres de las columnas y no se carga).
--   1. Si el producto ya existe en la localidad (mismo código) NO se crea: se actualiza.
--   2. Columnas nuevas (vienen en el archivo y no estaban en la base de datos):
--      critico: CRITICO (C = crítico)
--      valor_medida: VALOR_MEDIDA
--      codigo_proveedor_anterior: CODIGO_PROVEEDOR
--      pct_utilidad: PCT_UTILIDAD
--      pct_utilidad2: PCT_UTILIDAD2
--      codigo_visual: CODIGO_VISUAL
--      administracion_pm: ADMINISTRACION_PM (S/N: administra punto mínimo)
--      correlativo_bodega: CORRELATIVO_BODEGA
--      fecha_vigencia: FECHA_VIGENCIA
--      estado_anterior: ESTADO_ANTERIOR
--      covid: COVID (S/N)
--      clasificacion_lab: CLASIFICACION_LAB
--      revisado: REVISADO (S/N)
--      nombre_foto: NOMBRE_FOTO
--      lote: LOTE
--      precio_costo_dolar: PRECIO_COSTO_DOLAR
--      generico_anterior: GENERICO
--      proveedor_codigo_anterior: PROVEEDOR (código; se liga si existe en la localidad)
--      codigo_barras_anterior: CODIGO_BARRAS tal como venía
--      minimo_anterior: CANTIDAD_MINIMA
--      maximo_anterior: CANTIDAD_MAXIMA
--   Equivalencias: ESTADO A/I/E = ACTIVO/INACTIVO/DESCONTINUADO; ES_GENERICO SI/NO; ADMINISTRACION_PM S = punto
--   mínimo (con CANTIDAD_MINIMA y CANTIDAD_MAXIMA); la localidad 1 y 2 del archivo son la 3-01 y la 3-02; tipo de
--   producto, clasificación, tipo de medida, presentación, proveedor y bodega se ligan por su código en la
--   localidad (si un código no existe queda vacío y el código se conserva en la columna «anterior»).
--   Código de barras: se quitan los asteriscos y espacios (*7401168500013* = 7401168500013). Repetido en la
--   localidad (la base no lo permite): lo conserva el primero y el otro queda en codigo_barras_anterior: 3-02 producto 179 (7707236123710).
--   Punto mínimo con el mínimo mayor que el máximo (la base no lo permite): se carga sin punto mínimo y las
--   cantidades quedan en minimo_anterior y maximo_anterior: 3-01 134, 3-01 135, 3-01 152.
--   Los precios migrados en el script 103 (ACT_PRECIOS) se ligan solos al crear cada producto.
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.
-- Se ejecuta después del script 104.

alter table public.productos add column if not exists critico boolean;
alter table public.productos add column if not exists valor_medida numeric(14, 4);
alter table public.productos add column if not exists codigo_proveedor_anterior text;
alter table public.productos add column if not exists pct_utilidad numeric(7, 2);
alter table public.productos add column if not exists pct_utilidad2 numeric(7, 2);
alter table public.productos add column if not exists codigo_visual integer;
alter table public.productos add column if not exists administracion_pm text;
alter table public.productos add column if not exists correlativo_bodega integer;
alter table public.productos add column if not exists fecha_vigencia date;
alter table public.productos add column if not exists estado_anterior text;
alter table public.productos add column if not exists covid boolean;
alter table public.productos add column if not exists clasificacion_lab text;
alter table public.productos add column if not exists revisado boolean;
alter table public.productos add column if not exists nombre_foto text;
alter table public.productos add column if not exists lote text;
alter table public.productos add column if not exists precio_costo_dolar numeric(18, 4);
alter table public.productos add column if not exists generico_anterior text;
alter table public.productos add column if not exists proveedor_codigo_anterior integer;
alter table public.productos add column if not exists codigo_barras_anterior text;
alter table public.productos add column if not exists minimo_anterior numeric(14, 3);
alter table public.productos add column if not exists maximo_anterior numeric(14, 3);

do $migra$
declare
  v_org bigint;
  r record;
