      descripcion, codigo_producto, barras, barras_ant, generico, generico_ant, critico, valor_medida, cod_prov, pct1, pct2, visual, adm_pm, correlativo,
      vigencia, estado_ant, covid, clas_lab, revisado, foto, lote, costo, costo_dolar, marca) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    if v_loc is null then raise notice 'No existe la localidad 3-0%.', r.loc; continue; end if;
    select id into v_cla from public.clasificaciones_producto where localidad_id = v_loc and codigo = r.clasificacion;
    select id into v_tp from public.tipos_producto where localidad_id = v_loc and codigo = r.tipo and clasificacion_id = v_cla;
    select id into v_med from public.tipos_medida where localidad_id = v_loc and codigo = r.medida;
    select id into v_pre from public.presentaciones_producto where localidad_id = v_loc and codigo = r.presentacion;
    select id into v_prov from public.proveedores where localidad_id = v_loc and codigo = r.proveedor;
    select id into v_bod from public.bodegas where localidad_id = v_loc and codigo = r.bodega;
    if v_prov is null and coalesce(r.proveedor, 0) <> 0 then v_sinprov := v_sinprov + 1; end if;
    v_pm := upper(coalesce(r.adm_pm::text, '')) = 'S' and r.maximo >= r.minimo;
    insert into public.productos (organizacion_id, localidad_id, codigo, nombre, codigo_producto, clasificacion_id, tipo_producto_id, estado, marca,
