      bodega_id, descripcion, critico, valor_medida, codigo_proveedor_anterior, pct_utilidad, pct_utilidad2, codigo_visual, administracion_pm,
      correlativo_bodega, fecha_vigencia, estado_anterior, covid, clasificacion_lab, revisado, nombre_foto, lote, precio_costo_dolar, generico_anterior,
      proveedor_codigo_anterior, codigo_barras_anterior, minimo_anterior, maximo_anterior)
