      r.correlativo::integer, r.vigencia::date, r.estado_ant::text, r.covid::boolean, r.clas_lab::text, r.revisado::boolean, r.foto::text, r.lote::text,
      r.costo_dolar::numeric, r.generico_ant::text, nullif(r.proveedor, 0), r.barras_ant, r.minimo, r.maximo)
    on conflict (localidad_id, codigo) do update set
      nombre = excluded.nombre, codigo_producto = excluded.codigo_producto, clasificacion_id = excluded.clasificacion_id,
      tipo_producto_id = excluded.tipo_producto_id, estado = excluded.estado, marca = coalesce(excluded.marca, public.productos.marca),
      proveedor_id = excluded.proveedor_id, codigo_barras = excluded.codigo_barras, presentacion_id = excluded.presentacion_id,
      tipo_medida_id = excluded.tipo_medida_id, generico = excluded.generico, punto_minimo = excluded.punto_minimo, minimo = excluded.minimo,
      maximo = excluded.maximo, precio_costo = excluded.precio_costo, estante = excluded.estante, fila = excluded.fila, bloque = excluded.bloque,
      bodega_id = excluded.bodega_id, descripcion = excluded.descripcion, critico = excluded.critico, valor_medida = excluded.valor_medida,
      codigo_proveedor_anterior = excluded.codigo_proveedor_anterior, pct_utilidad = excluded.pct_utilidad, pct_utilidad2 = excluded.pct_utilidad2,
      codigo_visual = excluded.codigo_visual, administracion_pm = excluded.administracion_pm, correlativo_bodega = excluded.correlativo_bodega,
      fecha_vigencia = excluded.fecha_vigencia, estado_anterior = excluded.estado_anterior, covid = excluded.covid,
      clasificacion_lab = excluded.clasificacion_lab, revisado = excluded.revisado, nombre_foto = excluded.nombre_foto, lote = excluded.lote,
      precio_costo_dolar = excluded.precio_costo_dolar, generico_anterior = excluded.generico_anterior,
      proveedor_codigo_anterior = excluded.proveedor_codigo_anterior, codigo_barras_anterior = excluded.codigo_barras_anterior,
      minimo_anterior = excluded.minimo_anterior, maximo_anterior = excluded.maximo_anterior
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then v_n := v_n + 1; else v_a := v_a + 1; end if;
  end loop;
  -- Precios migrados (script 103) de productos que ya existían o se crearon: se ligan por código.
  update public.producto_precios pp set producto_id = p.id
  from public.productos p
  where pp.producto_id is null and p.localidad_id = pp.localidad_id and p.codigo = pp.producto_codigo and p.organizacion_id = v_org;
  get diagnostics v_ligados = row_count;
  raise notice '%', format('Productos: %s nuevos, %s actualizados, %s con proveedor que no existe en la localidad. Precios ligados ahora: %s.', v_n, v_a, v_sinprov, v_ligados);
end;
$migra$;

notify pgrst, 'reload schema';
